package com.pvp.travelmatch.repository; import com.pvp.travelmatch.entity.BoostedTravelPlan; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.time.LocalDateTime; import java.util.*; public interface BoostedTravelPlanRepository extends JpaRepository<BoostedTravelPlan,Long>{ Optional<BoostedTravelPlan> findByTravelPlanId(Long id); @Query("select b from BoostedTravelPlan b where b.travelPlan.id=:planId and b.active=true and b.expiresAt>:now") Optional<BoostedTravelPlan> findActive(@Param("planId")Long planId, @Param("now")LocalDateTime now); long countByActiveTrue(); }
